export function apiBase(value){const u=new URL(value);if(u.username||u.password||u.search||u.hash||!(u.protocol==='https:'||u.protocol==='http:'&&['127.0.0.1','localhost','[::1]'].includes(u.hostname)))throw Error('使用 HTTPS 地址，或本机 HTTP 地址；不在地址中填写凭据。');return u.href.replace(/\/$/,'');}
const id=value=>{if(typeof value!=='string'||!/^[-a-zA-Z0-9_]{1,128}$/.test(value))throw Error('API 返回的任务编号无效。');return value;};
async function encode(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',',2)[1]);r.onerror=()=>reject(Error('无法读取材料'));r.readAsDataURL(blob);});}
export async function materialPayload(p){if(!p.paper?.blob||!p.repository?.blob)throw Error('API 提交需要原始 PDF 与代码 ZIP；GitHub 目录请先下载为 ZIP。');if(p.paper.blob.size>20*1024**2||p.repository.blob.size>50*1024**2)throw Error('材料超过 PDF 20 MiB / ZIP 50 MiB 上限。');return {paper:{name:p.paper.name,content_base64:await encode(p.paper.blob)},code:{name:p.repository.name,content_base64:await encode(p.repository.blob)},scope:p.resources?.scope||''};}
export function validateAPIJob(v){if(!v||!['queued','running','completed','failed','cancelled'].includes(v.status))throw Error('API 任务状态无效。');id(v.id);if(v.source!=='model_api_static_review'||v.execution_performed!==false||v.scientific_validation!==false||typeof v.report_ready!=='boolean')throw Error('API 任务来源或执行范围不匹配。');return v;}
export function validateAPIReport(v,job){if(!v||v.format!=='articheck-api-static-review-v1'||v.job_id!==job.id||v.source!=='model_api_static_review'||v.execution_performed!==false||v.scientific_validation!==false||typeof v.review?.summary!=='string'||!Array.isArray(v.review.criteria)||v.review.criteria.length!==8||!Array.isArray(v.review.findings))throw Error('报告来源、任务身份或结构不匹配。');const keys=['scope','code','data','environment','settings','workflow','resources','results'];if(new Set(v.review.criteria.map(r=>r.dimension)).size!==8||v.review.criteria.some(r=>!keys.includes(r.dimension)||!['documented','needs_review','missing'].includes(r.status)||typeof r.note!=='string'))throw Error('静态审阅的维度或状态无效。');if(v.review.findings.some(f=>!f||['title','detail','suggestion'].some(k=>typeof f[k]!=='string')||f.page!=null&&(!Number.isInteger(f.page)||f.page<1)||f.file!=null&&typeof f.file!=='string'))throw Error('报告建议或出处格式无效。');return v;}
export class ReviewAPIClient{
 constructor(base,fetcher=fetch){this.base=apiBase(base);this.fetcher=(...args)=>fetcher.call(globalThis,...args);}
 async request(path,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),60000);try{const r=await this.fetcher(this.base+path,{method:body===undefined?'GET':'POST',headers:{'X-ArtiCheck-Client':'review-api',...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body),signal:controller.signal,redirect:'error',credentials:'omit'});let value;try{value=await r.json();}catch{throw Error('接口未返回 JSON，请核对 API 地址。');}if(!r.ok)throw Error(`${value.error?.code||r.status}：${value.error?.message||'API 请求失败'}`);return value;}finally{clearTimeout(timer);}}
 async health(){const v=await this.request('/v1/health');if(v.service!=='articheck-review-api'||v.version!==1||typeof v.configured!=='boolean')throw Error('不是兼容的 ArtiCheck Review API v1 服务。');return v;}
 async submit(p){return validateAPIJob(await this.request('/v1/reviews',await materialPayload(p)));}
 async get(key){return validateAPIJob(await this.request('/v1/reviews/'+id(key)));}
 async report(job){return validateAPIReport(await this.request('/v1/reviews/'+id(job.id)+'/report'),job);}
 async cancel(key){return validateAPIJob(await this.request('/v1/reviews/'+id(key)+'/cancel',{}));}
}
